    operations++;
    // Accumulate several lazy updates between reads.
    if (step % 8 !== 7) continue;
    for (let j = 0; j < 12; j++) {
      const lo = random(n + 1);
      const x = j === 0 ? Infinity : j === 1 ? -Infinity : (random(321) - 160) / 4;
      let expected = -1;
      for (let i = lo; i < n; i++) if (values[i] >= x) { expected = i; break; }
      assert.equal(tree.firstAtLeast(lo, x), expected, `search n=${n} step=${step}`);
      queries++;
    }
    for (let j = 0; j < 12; j++) {
      let a = random(n + 1), b = random(n + 1);
      if (a > b) [a, b] = [b, a];
      let sum = 0, max = -Infinity;
      for (let i = a; i < b; i++) { sum += values[i]; max = Math.max(max, values[i]); }
      assert.equal(tree.sum(a, b), sum, `sum n=${n} step=${step}`);
      assert.equal(tree.max(a, b), max, `max n=${n} step=${step}`);
      const index = random(n);
      assert.equal(tree.get(index), values[index]);
      queries += 3;
    }
    if (step % 64 === 63) assert.deepEqual(tree.toArray(), values);
  }
  assert.deepEqual(tree.toArray(), values);
}

for (const input of [undefined, null, {}, 'abc', [], [NaN], [Infinity], [-Infinity], ['1'], [1, , 3]]) {
  assert.throws(() => new RangeTree(input), RangeError);
}
const input = [1, 2, 3];
const tree = new RangeTree(input);
input[0] = 100;
assert.equal(tree.length, 3);
assert.throws(() => { tree.length = 10; }, TypeError);
assert.deepEqual(tree.toArray(), [1, 2, 3]);
const copy = tree.toArray();
copy[1] = 100;
assert.equal(tree.get(1), 2);
for (const method of ['assign', 'add', 'sum', 'max']) {
  for (const [l, r] of [[-1, 1], [0, 4], [2, 1], [0.5, 2], [0, NaN], ['0', 2], [0, Infinity]]) {
    assert.throws(() => tree[method](l, r, 7), RangeError);
  }
}
for (const method of ['assign', 'add']) {
  for (const v of [NaN, Infinity, -Infinity, '1', null, undefined, true]) {
    assert.throws(() => tree[method](0, 3, v), RangeError);
    assert.throws(() => tree[method](1, 1, v), RangeError);
  }
  for (let i = 0; i <= 3; i++) assert.equal(tree[method](i, i, 9), undefined);
}
for (let i = 0; i <= 3; i++) {
  assert.equal(tree.sum(i, i), 0);
  assert.equal(tree.max(i, i), -Infinity);
}
for (const i of [-1, 3, 0.5, NaN, Infinity, '0']) assert.throws(() => tree.get(i), RangeError);
for (const lo of [-1, 4, 0.5, NaN, Infinity, '0']) assert.throws(() => tree.firstAtLeast(lo, 1), RangeError);
for (const x of [NaN, '1', null, undefined, true]) assert.throws(() => tree.firstAtLeast(0, x), RangeError);
assert.equal(tree.firstAtLeast(3, -Infinity), -1);
assert.equal(tree.firstAtLeast(0, Infinity), -1);
assert.equal(tree.firstAtLeast(0, -Infinity), 0);
assert.deepEqual(tree.toArray(), [1, 2, 3]);
console.log(`Passed focused regressions, ${operations} mixed updates, ${queries} differential queries, and API boundary/error/aliasing checks.`);
